             end;
             player[person].sp := player[person].sp - 10;
             if random(100) < resistance then begin
                Print(7,'적은 독 공격을 저지 했다');
                exit;
             end;
             if random(40) > player[person].accuracy[2] then begin
                Print(7,'독 공격은 빗나갔다');
                exit;
             end;
             Print(4,name+'는 중독 되었다');
