            transdata[j-16] := transdata[j-16] - x1;
            k := k + x1;
         end;
         GotoXY(57,15); write('  ');
         GotoXY(57,15); write(k);
         GotoXY(57,j); write('  ');
         GotoXY(57,j); write(transdata[j-16]);
