Procedure ThunderEffect;
var
   ok : boolean;
begin
   ok := FALSE;
   SetPalette(6,6);
   RGB(6,40,20,0);
   repeat
      if random(1000) = 0 then
      if random(100) = 0 then begin
         RGB(6,10,20,63);
         delay(random(100)+20);
         RGB(6,40,20,0);
      end;
      if keypressed then c := readkey;
      if c = #27 then ok := true;
   until ok;
end;

Procedure PutSprite(x,y,number : integer);
begin
   PutImage(x,y,Chara^[number+28],AndPut);
   PutImage(x,y,Chara^[number],OrPut);
end;

Procedure StaffMessage;
begin
   page := 1 - page;
   SetActivePage(page);
   for j := 0 to 18 do
   for i := 0 to 32 do PutImage(i*20,j*20,Font^[47],CopyPut);
   SetColor(11);
   bHPrint(170,10,'이 게임의 끝마무리에 공헌한 인물');
   SetColor(10);
   PutSprite(40,40,4);
   cHPrint(120,42,'이름은 '+player[1].name+'. 바로 당신이다.');
   PutSprite(20,70,8); PutSprite(40,70,8); PutSprite(60,70,12);
   cHPrint(120,72,'Hydra, NOTICE 동굴의 보스였다.');
   PutSprite(20,100,10); PutSprite(40,100,14); PutSprite(60,100,18);
   PutSprite(20,120,11); PutSprite(40,120,15); PutSprite(60,120,19);
   cHPrint(120,112,'Huge Dragon, LOCKUP 동굴의 보스였다.');
   PutSprite(40,150,9);
   cHPrint(120,152,'Minotaur, 여기서 두번 등장하는 생물이다.');
   PutSprite(40,180,23);
   cHPrint(120,182,'Panzer Viper, DUNGEON OF EVIL 을 지키던 기계 생물.');
   PutSprite(40,210,22);
   cHPrint(120,212,'Black Knight, Necromancer 쪽의 제 2 인자 이다.');
   PutSprite(40,240,26);
   cHPrint(120,242,'ArchiMonk, Necromancer의 왼팔 역할의 실력자.');
   PutSprite(40,270,25);
   cHPrint(120,272,'ArchiMage, Necromancer의 오른팔인 마법사.');
   PutSprite(40,300,16); PutSprite(40,320,17);
   cHPrint(120,312,'Neo-Necromancer, 바로 당신의 목표였던 그자.');
   SetActivePage(1 - page);
end;

Procedure End_Demo;
var
   i, j : integer;
begin
   SetFont(0);
   FadeIn;
   SetBkColor(0);
   ClearDevice;
   EndMessage;
   FadeOut;
   setFont(1);
   StaffMessage;
   RGB(6,10,20,63);
   delay(40);
   RGB(6,40,20,0);
   delay(100);
   RGB(6,10,20,63);
   delay(100);
   RGB(6,40,20,0);
   ThunderEffect;
   ClearDevice;
   SetActivePage(page);
   SetVisualPage(page);
   while KeyPressed do c := ReadKey;
   y := 0; c := #255;
   j := 24; i := 1;
   ok := FALSE;
   repeat
      PutImage(600,(y div 20)*20,Font^[47],CopyPut);
      PutImage(600,(y div 20 + 1)*20,Font^[47],CopyPut);
      if y > 350 then y := 0;
      y := y + 2;
      PutSprite(600,y,j);
      if i = 1 then begin
         case j of
            20 : j := 24;
            24 : j := 21;
            21 : begin
                    j := 24;
                    i := 0;
                 end;
         end;
      end
      else begin
         case j of
            20 : begin
                    j := 24;
                    i := 1;
                 end;
            24 : j := 20;
            21 : j := 24;
         end;
      end;
      if KeyPressed then c := ReadKey;
      if c = #27 then ok := TRUE;
      delay(200);
   until ok;
   if AdLibOn then PlayOff;
   UnSound;
   asm
      mov ah,0
      mov al,3
      int $10
      mov ah,1
      mov ch,$20
      int $10
   end;
   FreeMem(font,13776); FreeMem(chara,13776);
   TextColor(7);
   TextBackGround(0);
   ClrScr;
   TextColor(7);
   Writeln(#13);
   RGB(7,0,0,0);
   SetPalette(15,15);
   RGB(15,0,0,0);
   TextColor(15);
   Writeln(#13);
   Writeln('                              << The End >>');
   Writeln('    " The Codex of Another Lore  vol. #1 " is made by Ahn Young-Kie.');
   TextColor(7);
   Writeln('                        You must be a genius !!!');
   for i := 1 to 63 do begin
      RGB(7,i,i,i);
      SetPalette(15,15);
      RGB(15,i,i,i);
      delay(10);
   end;
   delay(500);
   for i := 62 downto 42 do begin
      RGB(7,i,i,i);
      delay(15);
   end;
   asm
      mov ah,1
      mov ch,$13
      mov cl,$14
      int $10
   end;
   Halt;
end;
   
begin;
end.

