         1 : Return := 10;
         2 : Return := 11;
         3 : Return := 9;
         4 : Return := 12;
         5 : Return := 11;
         6 : Return := 13;
      end;
      if etc[14] = 6 then if map = 16 then Return := 14;
      if (etc[14]=6) and (map=2) then Return := 13
      else if Return = 13 then
      case etc[15] of
         0 : Return := 15;
