   m[5] := '초능력을 사용한다';
   m[6] := '여기서 쉰다';
   m[7] := '게임 선택 상황';
   k := Select(60,7,7,TRUE,TRUE);
   case k of
      0 : exit;
      1 : ViewParty;
      2 : ViewCharacter;
      3 : QuickView;
      4 : CastSpell;
      5 : Extrasense;
      6 : Rest;
      7 : GameOption;
   end;
end

source_units.original_source:
Unit LoreSpec;

INTERFACE

Uses
   Crt, Graph, UHanX, LoreSub, Voice, LoreBatt, LoreEnd;

 Procedure specialevent;


IMPLEMENTATION

Procedure specialevent_part1;

 function sgn(eq : integer) : integer;
 begin
    if eq > 0 then sgn := 1
    else if eq < 0 then sgn := -1
    else sgn := 0;
 end;

begin
   scroll(TRUE);
   case party.map of
      1 : begin
             Clear;
             if party.etc[32] and bit8 = 0 then begin
                talk('일행들은 100 인분의 식량을 발견했다.');
                if party.food > 155 then party.food := 255
                else party.food := party.food + 100;
                party.etc[32] := party.etc[32] or bit8;
             end
             else talk('우리들은 아무것도 발견할수 없었다.');
             x := x - x1; y := y - y1;
             scroll(TRUE);
          end;
      4 : begin
             Clear;
             if on(40,18) then begin
                message(7,' 일행은 공간 이동이 되었다');
                x := 46; y := 41;
                Silent_Scroll;
             end;
             if on(26,16) then begin
                Print(15,' 여기는 인간과 드래곤의 중간 종족이며  혼란');
                Print(15,'스런 세상을 피해 은둔하고있는 Draconian이란');
                Print(15,'자가 살고있는 피라밋이었다.');
                PressAnyKey;
                if party.etc[16] and bit2 > 0 then begin
                   message(7,' 그러나, 아무도 살고 있지 않았다.');
                   exit;
                end;
                if party.etc[5] = 0 then begin
                   Print(7,' 나는 Draconian이라고 하오. 이런곳까지 사람');
                   Print(7,'이 찾아오리라고는 생각하지 못했는데 참 의외');
                   Print(7,'로군요. 나는 숨어 지내는 오랜 세월동안에 여');
                   Print(7,'러가지 학문을 연구하고 있었소.  특히 천문학');
                   Print(7,'에 대해서는 특별히 전염하여 다루었소.  내가');
                   Print(7,'그동안 알아낸 지식들은 다음과 같은 것이오.');
                   Print(7,' 지금 우리가 살고있는 지구는 태양계에서  세');
                   Print(7,'번째로 위치한 행성인데 이상하게도 위성인 달');
                   Print(7,'이 지구보다도 더 오래되었다는 사실이 연구되');
                   Print(7,'었소. 또한 이 지구가 세차운동에 의해 2 등성');
                   Print(7,'이었던 북극성이 다른 별로 바뀐다는걸 알았소');
                   Print(7,' 물리학에서 알아낸것은, 중수반응에서 매질의');
                   Print(7,'차이로 빛이 속도가 느려진 틈을 이용해 빛 보');
                   Print(7,'다 빠른 입자가 생겨났소. 하지만 절대적인 빛');
                   Print(7,'의 속도에는 미치지 못했지만 말이오.  이것을');
                   Print(7,'잘만 이용하면 미래로의 타임머신이  가능하다');
                   Print(7,'는 걸 입증할 수가 있소.');
                   Print(7,' 사실 이런것은 당신에게는 별 의미가 없는 것');
                   Print(7,'일지도 모르오. 하지만 마지막으로 알아낸것은');
                   Print(7,'바로 당신이 응징하고자 하는  Necromancer 의');
                   Print(7,'출처에 관한 것이오. 당신은 시그너스 X1과 같');
                   Print(7,'은 블랙홀에 대해서 알고있을 것이오. 이런 물');
                   Print(7,'리학적인 파라독스에 의해 그는 생겨났던것이오.');
                   PressAnyKey;
                   Print(7,' 지금 우리가 있는 3차원 위에 또 다른 차원이');
                   Print(7,'있다고 생각하오?  생각은 하더라도 눈으로 확');
                   Print(7,'인은 못해봤을것이오. 우리는 2차원을 인식 할');
                   Print(7,'수가 있소.  하지만 실제로 2차원에  살고있는');
                   Print(7,'생물은 자신의 차원은 인식해도 우리가 살고있');
                   Print(7,'는 3차원은 인식할 수가 없는 것이오. 그의 차');
                   Print(7,'원에는 우리의 차원이  존재하지 않기  때문에');
                   Print(7,'개념을 잡을수가 없는 것이오.  마찬가지로 우');
                   Print(7,'리 또한 지금의 차원보다 한 차원 높은 4 차원');
                   Print(7,'을 개념을 잡기가 어려운 것이오.');
                   Print(7,' 어떤이는 4차원은 시간의 축이 보태어 진다고');
                   Print(7,'하는 이론을 세우더군요.  하지만 나의 이론은');
                   Print(7,'시간은 모든 차원의 기준이며 4차원에 국한 되');
                   Print(7,'지는 않는다는 생각이오. 3차원에서는 동 시간');
                   Print(7,'대에 무한한 2차원을 포함 하듯이 4차원에서는');
                   Print(7,'동 시간대에  무한한 3차원을 포함하고 있다는');
                   Print(7,'이론이 성립되오. 말이 조금은 빗나갔지만  이');
                   Print(7,'이론으로 Necromancer의 출처를 해명해 보겠소');
                   Print(7,' 방금 말했듯이 3차원은 이 공간만이 존재하는');
                   Print(7,'것은 아니오. 동 시대를 살아가는 다른 공간도');
                   Print(7,'인정해야 한다는 말이오.  그 공간들을 이어주');
                   Print(7,'는 것이 바로 블랙 홀이란 것이지요.  그는 원');
                   Print(7,'래 그가 있던 공간에서 블랙 홀을 통해서 다른');
                   Print(7,'공간으로 가려고 시도를 했고 웜 홀을 통해 시');
                   Print(7,'공간을 가로질러 오래전 우리의 공간에 화이트');
                   Print(7,'홀이 생기는 틈을 이용하여 내려왔던 것이오.');
                   Print(7,' 하지만 3차원에 사는 나로서는 그가 전에  있');
                   Print(7,'던 공간에서 왜 이쪽으로 왔는지  알수가 없었');
                   Print(7,'지요. 그래서 그와 같이 이 공간으로 들어왔던');
                   Print(7,'심복들을 통해 그 사정을 알게 되었소.');
                   Print(7,' Necromacer는 저쪽의 공간에서도 지금과 마찬');
                   Print(7,'가지로 차원을 통해 그 공간에 도달했소. 역시');
                   Print(7,'거기서도 악을 뿌리며 거기의 생명체들을 위협');
                   Print(7,'했소. 하지만 어떤 선택되어진 6인의 용사들에');
                   Print(7,'의해 쫒겨나서 여기로 온것이오.  지금의 당신');
                   Print(7,'들과 비슷하다고 생각되지 않소? 그렇소. 다른');
                   Print(7,'공간의 당신들에게 쫒겨난후 다시 여기서 당신');
                   Print(7,'들을 또 만나게 된것이오. Necromancer와 당신');
                   Print(7,'들의 운명은 언제까지나 쫒고 쫒기며 대립하여');
                   Print(7,'야하는 운명으로 탄생되었던 것이오. 이런  이');
                   Print(7,'유에서 당신은 그를 반드시 무찌를 수가  있다');
                   Print(7,'는 근거가 되는 것이오.');
                   Print(7,' 당신들의 건투를 빌어주겠소.');
                   talk('');
                end
                else begin
                   Print(7,' 나의 운명을 생각해 보니  나 역시  당신들을');
                   Print(7,'필연적으로 만나 Necromancer를 물리쳐야 한다');
                   Print(7,'는걸 깨닭았소. 당신들 일행의 제일 뒤에서 도');
                   Print(7,'와주고 싶소. 어떻소.');
                   m[0] := '';
                   m[1] := '저도 바라던 차입니다';
                   m[2] := '별로 좋지는 않군요';
                   k := select(140,2,2,FALSE,TRUE);
                   if k = 0 then exit;
                   if k = 1 then begin
                      enemydata[62].level := 17;
                      join(62,6);
                      enemydata[62].level := 19;
                      Display_Condition;
                      party.etc[16] := party.etc[16] or bit2;
                   end;
                   if k = 2 then begin
                      Print(7,' 다시 생각해보니 나는 당신들과 같이 싸울 운');
                      Print(7,'명이 아닌것 같소.');
                      PressAnyKey;
                   end;
                end;
             end;
             if on(20,39) then begin
                if party.etc[16] and bit1 > 0 then begin
                   x := 46; y := 41;
                   scroll(TRUE);
                   Print(7,' 이제는 더 이상 할말이 없소.');
                   PressAnyKey;
                   exit;
                end;
                aux := SoundOn; SoundOn := false;
                Print(7,' 나는 Ancient Evil 이란 존재이오. 이제 나는');
                Print(7,'육신은 없는 영이오. 당신은 Lord Ahn 을 만나');
                Print(7,'보았겠군요. 그리고 우리들의 운명적인 만남도');
                Print(7,'역시 예시 받았겠군요.');
                Print(7,' 사실이야 어떻든 당신에게 이 대륙에서의  할');
                Print(7,'일을 말해 주겠소.');
                PressAnyKey;
                x := 48; y := 57;
                scroll(FALSE);
                Print(7,' 여기는 EVIL GOD 라는 동굴이오. 여기의 보스');
                Print(7,'는 Crab God인데 적 자체는 별거 아니지만  떼');
                Print(7,'를 지어서 다니기 때문에 약간의 애를 먹을 것');
                Print(7,'이오. 7갈래의 길중에서 한곳에 봉인이 숨겨져');
                Print(7,'있을 것이오.');
                PressAnyKey;
                x := 82; y := 16;
                scroll(FALSE);
                Print(7,' 여기는 Muddy 라는 동굴이오.  여기의 보스는');
                Print(7,'Astral Mud라는 자인데  그리 실력이 있다고는');
                Print(7,'볼수가 없소. 다만 동굴 자체가 어려운 미로라');
                Print(7,'는 것과 시야가 좁아지는 불편등은 감수해야만');
                Print(7,'할 것이오. 그리고 마지막에 3마리의 Dragon과');
                Print(7,'7마리의 Mud-Man을 거쳐야만 그가 나타나기 때');
                Print(7,'문에 약간 까다로울 것이오.');
                PressAnyKey;
                x := 16; y := 15;
                soundon := aux;
                scroll(TRUE);
                Print(7,' 여기는 이 대륙의 외진곳이오. 여기서는 어떤');
                Print(7,'만남이 기다리고 있을 것이오.');
                PressAnyKey;
                party.etc[16] := party.etc[16] or bit1;
             end;
          end;
      6 : if on(62,82) then begin
             Clear;
             message(7,'일행은 상자 속에서 약간의 금을 발견했다.');
             party.gold := party.gold + 1000;
             map[62,82] := 44;
          end
          else if on(51,12) or on(52,12) then begin
             if party.etc[50] and bit2 > 0 then begin
                Clear;
                if party.etc[50] and bit3 > 0 then begin
                   Print(7,' 다시 돌아오다니, '+player[1].name);
                   Print(7,' 이번에는 기어이 네놈들을 해치우고야 말겠다');
                   talk('. 나의 친구들도 이번에 거들것이다.');
                   enemynumber := 7;
                end
                else begin
                   Print(7,' 아니! 당신이 우리들을 배신하고 죄수를 풀어');
                   Print(7,'주다니... 그렇다면 우리들은 결투로서 당신들');
                   talk('과 승부할수 밖에 없군요.');
                   party.etc[50] := party.etc[50] or bit3;
                   enemynumber := 2;
                end;
                for i := 1 to enemynumber do begin
                   joinenemy(i,26);
                   with enemy[i] do begin
                      name := 'Soldier'+chr(48+i);
                      special := 0;
                      castlevel := 0;
                      E_number := 1;
                   end;
                end;
                Displayenemies(TRUE);
                if player[6].name = 'Mad Joe' then begin
                   Clear;
                   Print(7,' 우리들 뒤에 있던  Mad Joe가 전투가 일어나');
                   Print(7,'자마자 도망을 가버렸다.');
                   player[6].name := '';
                   Display_Condition;
                   Pressanykey;
                end;
                BattleMode(FALSE);
                if party.etc[6] = 255 then exit;
                if party.etc[6] = 0 then begin
                   Clear;
                   Print(15,'당신들은 수감소 병사들을 물리쳤다.');
                   PressAnyKey;
                   party.etc[50] := party.etc[50] or bit3;
                   map[51,12] := 44; map[52,12] := 44;
                   map[50,11] := 44; map[53,11] := 44;
                   Silent_Scroll;
                end;
             end;
          end
          else if on(41,79) then begin
             if party.etc[50] and bit4 = 0 then begin
                party.etc[50] := party.etc[50] or bit4;
                for i := 1 to 3 do begin
                   delay(500);
                   dec(x);
                   Scroll(TRUE);
                end;
                map[41,79] := 44;
                Print(7,' 일행은 가장 기본적인 무기로  모두  무장을');
                talk('하였다.');
                for i := 1 to 6 do
                with player[i] do
                if (name <> '') and (weapon = 0) and (class <> 5) then begin
                   weapon := 1;
                   wea_power := 5;
                end;
             end;
          end
          else if wantexit then begin
             if party.etc[31] and bit1 = 0 then begin
                Clear;
                Print(7,' 당신이 LORE 성을 떠나려는 순간 누군가가 당신을 불렀다.');
                PressAnyKey;
                aux := soundon;
                soundon := FALSE;
                for i := y - 4 to y - 1 do begin
                   map[x,pred(i)] := 44;
                   map[x,i] := 48;
                   scroll(TRUE);
                end;
                soundon := aux;
                Print(7,' 나는 Skeleton이라 불리는 종족의 사람이오.');
                Print(7,' 우리 종족의 사람들은 나를 제외하고는  모두');
                Print(7,'Necromancer에게 굴복하여 그의 부하가 되었지');
                Print(7,'만 나는 그렇지 않소. 나는 Necromancer 의 영');
                Print(7,'향을 피해서 이곳 LORE 성으로 왔지만 나의 혐');
                Print(7,'오스런 생김새 때문에 이곳 사람들에게 배척되');
                Print(7,'어서 지금은 어디로도 갈 수 없는 존재가 되었');
                Print(7,'소. 이제 나에게 남은 것은 Necromancer 의 타');
                Print(7,'도 밖에 없소.  그래서  당신들의 일행에 끼고');
                Print(7,'싶소.');
                Print(7,''); Print(7,''); Print(7,''); Print(7,''); Print(7,'');
                m[0] := '';
                m[1] := '당신을 환영하오.';
                m[2] := '미안하지만 안되겠소.';
                k := select(125,2,2,FALSE,TRUE);
                if k = 1 then begin
                   join(19,6);
                   Display_Condition;
                end
                else asyouwish;
                PressAnyKey;
                party.etc[31] := party.etc[31] or bit1;
             end;
             with party do begin
                xaxis := 20; yaxis := 12; map := 1;
             end;
             load;
          end
          else begin
             dec(y); scroll(TRUE);
          end;
      7 : begin
             Clear;
             if x = 50 then
             if wantenter('GROUND GATE') then begin
                with party do begin
                   xaxis := 50; yaxis := 10; map := 8;
                end;
                load;
                scroll(TRUE);
             end;
             if (x = 30) or (x = 32) then begin
                map[31,y] := 45;
                putimage(100+(31-x)*20,100,Font^[45],CopyPut);
             end;
             if y = 71 then begin
                if wantexit then begin
                   with party do begin
                      xaxis := 77; yaxis := 57; map := 1;
                   end;
                   load;
                end
                else begin
                   dec(y); scroll(TRUE);
                end;
             end;
          end;
      8 : begin
             Clear;
             if x = 50 then
             if wantenter('GROUND GATE') then begin
                with party do begin
                   xaxis := 50; yaxis := 10; map := 7;
                end;
                load;
                scroll(TRUE);
             end;
             if y = 71 then begin
                if wantexit then begin
                   with party do begin
                      xaxis := 19; yaxis := 27; map := 2;
                   end;
                   load;
                end
                else begin
                   dec(y); scroll(TRUE);
                end;
             end;
          end;
      9 : begin
             Clear;
             if (on(10,24)) and (party.etc[35] and bit1 = 0) then begin
                findgold(5000);
                party.etc[35] := party.etc[35] or bit1;
             end;
             if (on(12,26)) and (party.etc[35] and bit2 = 0) then begin
                findgold(5000);
                party.etc[35] := party.etc[35] or bit2;
             end;
             if (on(15,25)) and (party.etc[35] and bit3 = 0) then begin
                findgold(5000);
                party.etc[35] := party.etc[35] or bit3;
             end;
             if (on(16,23)) and (party.etc[35] and bit4 = 0) then begin
                findgold(5000);
                party.etc[35] := party.etc[35] or bit4;
             end;
             if (on(18,27)) and (party.etc[35] and bit5 = 0) then begin
                findgold(5000);
                party.etc[35] := party.etc[35] or bit5;
             end;
             if (y=10) and (party.etc[15]<5) then begin
                Message(13,'알수없는 힘이 당신을 배척합니다.');
                inc(y);
                scroll(TRUE);
             end;
             if y = 5 then
             if wantenter('SWAMP GATE') then begin
                face := 1;
                for i := 4 downto 0 do begin
                   delay(1000);
                   putimage(100,20*(i+1),font^[44],copyput);
                   if i > 0 then begin
                      PutImage(100,20*i,chara^[face+28],andPut);
                      PutImage(100,20*i,chara^[face],orPut);
                   end;
                end;
                if party.etc[35] and bit6 = 0 then begin
                   Print(15,' SWAMP GATE 로 들어가고 있는 당신에게  허공');
                   Print(15,'에서 갑자가 누군가가 말을 꺼낸다');
                   PressAnyKey;
                   cPrint(7,11,' 나는 LORE 성의 성주 ','Lord Ahn',' 이오.');
                   Print(7,' 역시 내가 예상한 대로 당신들은 훌륭한 용사');
