Procedure RGB(Color, Red, Green, Blue : byte); assembler;
asm
   mov dx,$3c8;
   mov al,Color;
   out dx,al;
   inc dx;
   mov al,Red;
   out dx,al;
   mov al,Green;
   out dx,al;
   mov al,Blue;
   out dx,al;
end;

Procedure Clear;
var
   i : integer;
begin
   for i:= 0 to 1 do begin
      page := 1 - page;
      SetActivePage(page);
      Bar(231,21,616,198);
   end;
   yline := 30;
   hany := 32;
end;

Procedure PressAnyKey;
begin
   setcolor(14);
   HPrintXY4Select(250,180,'아무키나 누르십시오 ...');
   while keypressed do c := readkey;
   c := readkey;
   if c = #0 then c := readkey;
   Clear;
end;

Procedure Scroll(character : boolean);
var AuxX, AuxY : shortint;
begin
   while KeyPressed do c:= readkey;
   page := 1 - page;
   SetActivePage(page);
   if (position = den) and (party.etc[1] = 0) then begin
      setfillstyle(1,0);
      bar(20,20,200,200);
      setcolor(8);
      HPrintXY(94,96,'어둠');
   end
   else begin
      AuxX := x - 5; AuxY := y - 5;
      if scrolltype <> normal then begin
         setfillstyle(scrollform,scrollcolor);
         bar(20,20,200,200);
      end;
      for j := 1 to 9 do for i := 1 to 9 do PutImage(i*20,j*20,font^[map[i+AuxX,j+AuxY]],putstyle);
      if character then begin
         PutImage(100,100,chara^[face+28],andPut);
         PutImage(100,100,chara^[face],orPut);
      end;
   end;
   if soundon then begin
      Sound(20); Delay(5);
   end;
   SetVisualPage(page);
   NoSound;
   setfillstyle(solidfill,DarkGray);
end;

Procedure Silent_Scroll;
begin
   aux := soundon; soundon := FALSE;
   scroll(TRUE);
   soundon := aux;
end;

Procedure AuxScroll(x_value,y_value : shortint; tilenumber : byte);
var AuxX, AuxY : shortint;
begin
   while KeyPressed do c:= readkey;
   page := 1 - page;
   SetActivePage(page);
   if (position = den) and (party.etc[1] = 0) then begin
      setfillstyle(1,0);
      bar(20,20,200,200);
      setcolor(8);
      outtextxy(78,100,'Darkness');
   end
   else begin
      AuxX := x - 5; AuxY := y - 5;
      if scrolltype <> normal then begin
         setfillstyle(scrollform,scrollcolor);
         bar(20,20,200,200);
      end;
      for j := 1 to 9 do for i := 1 to 9 do PutImage(i*20,j*20,font^[map[i+AuxX,j+AuxY]],putstyle);
      PutImage(100,100,chara^[face+28],andPut);
      PutImage(100,100,chara^[face],orPut);
      if (x_value>-5) and (x_value<5) and (y_value>-5) and (y_value>5) then
         PutImage(x_value*20+100,y_value*20+100,font^[tilenumber],copyput);
   end;
   SetVisualPage(page);
   NoSound;
   setfillstyle(solidfill,DarkGray);
end;

Procedure setscrolltype(form : scrolltypes);
begin
   scrolltype := form;
   if form = normal then begin
      putstyle := copyput;
      party.etc[12] := 0;
   end
   else putstyle := orput;
   case form of
      snow : begin
                scrollform := SolidFill;
                scrollcolor := Blue;
                party.etc[12] := 1;
             end;
      rain : begin
                scrollform := LtSlashFill;
                scrollcolor := Blue;
                party.etc[12] := 2;
             end;
      autumn : begin
                  scrollform := SolidFill;
                  scrollcolor := Brown;
                  party.etc[12] := 3;
               end;
      wilderness : begin
                      scrollform := 9;
                      scrollcolor := Blue;
                      party.etc[12] := 4;
                   end;
      strongrain : begin
                      scrollform := 6;
                      scrollcolor := Blue;
                      party.etc[12] := 5;
                   end;
   end;
end;

Function exist(person : integer) : boolean;
begin
   exist := FALSE;
   if (player[person].name <> '') and (player[person].unconscious = 0) and
   (player[person].dead = 0) and (player[person].hp > 0) then exist := TRUE;
end;

Procedure EPrint(color : integer; s1 : string);
begin 
   SetColor(color);
   yline := yline + 14;
   if yline > 184 then begin
      yline := 184;
      c := ReadKey;
      if c = #0 then c := readkey;
      asm
         mov ah,6;
         mov al,1;
         mov bh,8;
         mov cl,29;
         mov ch,2;
         mov dl,75;
         mov dh,13;
         int $10;
      end;
   end;
   if length(s1) < 45 then OutTextXY(250,yline,s1)
   else begin
      s := copy(s1,45,length(s1)-44);
      delete(s1,45,length(s1)-44);
      OutTextXY(250,yline,s1);
      Print(color,s);
   end;
end;

