         m[1] := '없습니다';
         m[2] := '본 게임 데이타';
         m[3] := '게임 데이타 1 (부)';
         m[4] := '게임 데이타 2 (부)';
         m[5] := '게임 데이타 3 (부)';
         k := select(65,5,5,TRUE,TRUE);
         if k > 1 then begin
            LoadNo := chr(k+47);
            setcolor(11);
            HPrintXY(280,80,'저장했던 게임을 다시 불러옵니다');
            LoadFont := FALSE; Load; Scroll(TRUE); Display_Condition;
            LoadNo := '1'; party.etc[6] := 255;
            Clear;
            exit;
         end;
      end;
   end;
   if AdLibOn then PlayOff;
   UnSound;
   asm
      mov ah,0
      mov al,3
      int $10
      mov ah,1
      mov ch,$20
      int $10
   end;
   FreeMem(font,13776); FreeMem(chara,13776);
   TextColor(7);
   TextBackGround(0);
   ClrScr;
   TextColor(7);
   Writeln(#13);
   RGB(7,0,0,0);
   Writeln('Feel your RPG imagination !!');
   for i := 1 to 63 do begin
      RGB(7,i,i,i);
      delay(15);
   end;
   delay(500);
   for i := 62 downto 42 do begin
      RGB(7,i,i,i);
      delay(15);
   end;
   asm
      mov ah,1
      mov ch,$13
      mov cl,$14
      int $10
   end;
   Halt;
end;

Procedure DetectGameOver;
var
   i,j : integer;
begin
   j := 0;
   for i := 1 to 6 do if exist(i) then inc(j);
   if j = 0 then begin
      party.etc[6] := 255; { Poisoned to death }
      gameover;
   end;
end;

Function SelectEnemy : integer;
var
   number,color,y1 : integer;
   move : boolean;
begin
   ok := FALSE;
   number := 1;
   repeat
   with enemy[number] do begin
      case hp of
         0 : color := 8;
         1..19 : color := 12;
         20..49 : color := 4;
         50..99 : color := 6;
         100..199 : color := 14;
         200..299 : color := 2
         else color := 10;
      end;
      if dead = TRUE then color := 0;
      SetFillStyle(1,7);
      Bar(40,20*number+18,178,20*number+30);
      SetColor(color);
      if color = 0 then setcolor(7);
      OutTextXY(50,20*number+20,name);
      y1 := 0; move := FALSE; c := ReadKey;
      if c = #0 then begin
         c := ReadKey;
         move := TRUE;
         case c of
            #72 : y1 := -1;
            #80 : y1 := 1
            else move := FALSE;
         end;
      end;
      if c = #13 then ok := TRUE;
      if move or ok then begin
         SetFillstyle(1,0);
         Bar(40,20*number+18,178,20*number+30);
         SetColor(color);
         OutTextXY(50,20*number+20,name);
         number := number + y1;
         if number<1 then number := enemynumber;
         if number>enemynumber then number := 1;
      end;
   end;
   until ok;
   SetFillStyle(1,8);
   SelectEnemy := number;
end;

Function ChooseWhom(clean : boolean) : integer;
var
   i,j,k : integer;
begin
   m[0] := '';
   j := 0;
   for i := 1 to 6 do
   if player[i].name <> '' then begin
      inc(j);
      m[j] := player[i].name;
   end;
   SetColor(10);
   HPrintXY(265,70,'한명을 고르시오 ---');
   k := Select(90,j,j,clean,TRUE);
   if k = 0 then begin
      ChooseWhom := 0;
      exit;
   end;
   j := 0;
   for i := 1 to 6 do
   if player[i].name <> '' then begin
      inc(j);
      if j = k then ChooseWhom := i;
   end;
end;

