Unit LoreTalk;

INTERFACE

Uses
   Crt, Graph, UHanX, LoreSub;

 Procedure talkmode;


IMPLEMENTATION

Procedure talkmode;
begin
  Clear;
  case party.map of
     6 : begin
      if at(9,64) then begin
         Print(7,' 당신이 모험을 시작한다면, 많은 괴물들을 만날 것이오.');
         s := ' 무엇보다도, Serpent 와 Insects 와 Python 은';
         talk(s+' 맹독이 있으니 주의 하시기 바라오.');
      end;
      if at(72,73) then talk('Orc 는 가장 하급 괴물이오.');
      if at(51,72) then begin
         if party.etc[50] and bit5 = 0 then begin
            i := 100 + 20 * x1;
            j := 100 + 20 * y1;
            putimage(i,j,font^[44],CopyPut);
            putimage(i,j,chara^[24+28],AndPut);
            putimage(i,j,chara^[24],OrPut);
            Print(7,' 당신이  Necromancer에 진정으로  대항하고자');
            Print(7,'한다면, 이 성의 바로위에 있는 피라밋에 가보');
            Print(7,'도록하시오. 그 곳은 Necromancer와 동시에 바');
            cPrint(7,11,'다에서 떠오른 ','또다른 지식의 성전','이기 때문이');
            Print(7,'오.  당신이 어느 수준이 되어 그 곳에 들어간');
            Print(7,'다면  진정한 이 세계의 진실을 알수 있을것이');
            talk('오.');
            party.etc[50] := party.etc[50] or bit5;
            putimage(i,j,font^[53],CopyPut);
         end
         else begin
            Print(7,' `MENACE'' 속에는 Dwarf, Giant, Wolf, Python');
            talk('같은 괴물들이 살고 있소.');
         end;
      end;
      if at(58,74) then begin
         s := ' 나의 부모님은 Python 의 독에 의해 돌아 가셨습니다.';
         talk(s+' Python 은 정말 위험한 존재입니다.');
      end;
      if at(63,27) then begin
         Print(7,' 단지 Lord Ahn 만이 능력 상으로 Necromancer 에게 도전할 수 있습니다.');
         s := ' 하지만 Lord Ahn 자신이 대립을 싫어해서, 현재는';
         Talk(s+' Necromancer 에게 대항할 자가 없습니다.');
      end;
      if at(90,82) then
         talk(' 우리는 Ancient Evil을 배척하고 Lord Ahn님을 받들어야 합니다.');
      if at(94,68) then begin
         talk(' 우리는 MENACE 의 동쪽에 있는 나무로부터 많은 식량을 얻은적이 있습니다.');
      end;
      if at(19,53) then begin
         Print(10,' 이 세계의 창시자는 안 영기님 이시며, 그는 위대한 프로그래머 입니다.');
         PressAnyKey;
      end;
      if at(13,27) or at(18,27) then begin
         s := ReturnSex(1);
         Print(7,' 어서 오십시오. 여기는 LORE 주점입니다.');
         if random(2) = 0 then
            talk(' 거기 '+s+'분 어서 오십시오.')
         else
            talk(' 위스키에서 칵테일까지 마음껏 선택하십시오.');
      end;
      if at(21,33) then talk('...');
      if at(10,30) then talk('요새 무덤쪽에서 유령이 떠돈다던데...');
      if at(13,32) then talk('하하하, 자네도 한번 마셔보게나.');
      if at(15,35) then begin
         Print(7,' 이제 Lord Ahn의 시대도 끝나가는가 ? 그까짓');
         Print(7,'Necromancer라는 작자에게 쩔쩔 매는 꼴이라니');
         Print(7,'...  차라리 내가 나가서 그 놈과 싸우는게 났');
         talk('겠다.');
      end;
      if at(18,33) then begin
         Print(7,' 당신은 Skeleton 족의 한명이 우리와 함께 생');
         Print(7,'활하려 한다는 것에 대해서 어떻게 생각하십니');
         Print(7,'까 ?  저는 그 말을 들었을때 너무 혐오스러웠');
         Print(7,'습니다. 어서 빨리 그 살아있는 뼈다귀를 여기');
         talk('서 쫒아냈으면 좋겠습니다.');
      end;
      if at(21,36) then talk(' ... 끄~~윽 ... ...');
      if at(18,38) then begin
         Print(7,' 이보게 자네, 내말 좀 들어 보게나.  나의 친');
         Print(7,'구들은 이제 이 세상에 없다네. 그들은 너무나');
         Print(7,'도 용감하고 믿음직스런 친구들이었는데... 내');
         Print(7,'가 다리를 다쳐 병원에 있을 동안 그들은 모두');
         Print(7,'이 대륙의 평화를 위해 LORE 특공대에 지원 했');
         Print(7,'다네.  하지만 그들은 아무도 다시는 돌아오지');
         Print(7,'못했어.  그런 그들에게 이렇게 살아있는 나로');
         Print(7,'서는 미안할 뿐이네  그래서 술로 나날을 보내');
         Print(7,'고 있지. 죄책감을 잊기위해서 말이지...');
         talk('');
      end;
      if at(72,78) then begin
         Print(7,' 물러나십시오.  여기는 용사의 유골들을 안치');
         talk('해 놓은 곳입니다.');
      end;
      if at(63,76) and (party.etc[50] and bit1 = 0) then begin
         Print(7,' 당신이  한 유골 앞에 섰을때  이상한 느낌과');
         talk('함께 먼곳으로 부터 어떤 소리가 들려왔다.');
         Print(13,' 안녕하시오. 대담한 용사여.');
         Print(13,' 당신이 나의 잠을 깨웠소 ?  나는 고대에 이');
         Print(13,'곳을 지키다가 죽어간 기사 Jr. Antares 라고');
         Print(13,'하오.  저의 아버지는 Red Antares 라고 불리');
         Print(13,'웠던 최강의 마법사였소.  그는 말년에  어떤');
         Print(13,'동굴로 은신을 한 후 아무에게도 모습을 나타');
         Print(13,'내지 않았소.  하지만 당신의 운명은 나의 아');
         Print(13,'버지를 만나야만하는 운명이라는 것을 알수있');
         Print(13,'소.  반드시 나의 아버지를 만나서 당신이 알');
         Print(13,'지 못했던 새로운 능력들을 배우시오. 그리고');
         Print(13,'나의 아버지를 당신의 동행으로 참가시키도록');
         Print(13,'하시오. 물론 좀 어렵겠지만 ...');
         talk('');
         Print(13,' 아참,  그리고 내가 죽기전에 여기에 뭔가를');
         Print(13,'여기에 숨겨 두었는데  당신에게 도움이 될지');
         Print(13,'모르겠소. 그럼, 나는 다시 오랜 잠으로 들어');
         Print(13,'가야 겠소.');
         PressAnyKey;
         for i := 79 to 81 do  map[62,i] := 44;
         map[62,82]:=0; map[62,83]:=14;
         Silent_Scroll;
         party.etc[50] := party.etc[50] or bit1;
      end;
      if at(24,50) then begin
         Print(7,' 힘내게, '+player[1].name);
         Print(7,' 자네라면 충분히 Necromancer를 무찌를수 있');
         talk('을 걸세. 자네만 믿겠네.');
      end;
      if at(24,54) then begin
